-- Add questions for Creative Problem Solving
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer_index, explanation, difficulty, points, display_order) VALUES
('85ec5362-03d7-4922-9300-1592e3c5abec', 'A company is losing customers due to long wait times. What is the most creative solution?', 'multiple_choice', '[{"text": "Hire more staff immediately", "value": "a"}, {"text": "Implement a virtual queue system with entertainment", "value": "b"}, {"text": "Reduce service quality to serve faster", "value": "c"}, {"text": "Ignore the problem", "value": "d"}]', 1, 'A virtual queue system with entertainment addresses the problem creatively by making wait time more enjoyable rather than just reducing it.', 'intermediate', 1, 1),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'How would you use a brick in an unconventional way?', 'multiple_choice', '[{"text": "As a paperweight", "value": "a"}, {"text": "As a smartphone stand with carved grooves", "value": "b"}, {"text": "As a weapon", "value": "c"}, {"text": "As a doorstop", "value": "d"}]', 1, 'Creating a smartphone stand by carving grooves shows creative problem-solving by transforming the brick into a useful modern tool.', 'intermediate', 1, 2),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'Your team has a tight budget for a marketing campaign. What approach shows creative thinking?', 'multiple_choice', '[{"text": "Cancel the campaign", "value": "a"}, {"text": "Create viral user-generated content contest", "value": "b"}, {"text": "Buy expensive ads anyway", "value": "c"}, {"text": "Do nothing", "value": "d"}]', 1, 'A user-generated content contest leverages creativity to get marketing reach without high costs through community engagement.', 'intermediate', 1, 3),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'Which approach best demonstrates lateral thinking?', 'multiple_choice', '[{"text": "Following standard procedures", "value": "a"}, {"text": "Combining unrelated ideas to solve problems", "value": "b"}, {"text": "Avoiding risks", "value": "c"}, {"text": "Working harder on the same approach", "value": "d"}]', 1, 'Lateral thinking involves making connections between unrelated concepts to find innovative solutions.', 'intermediate', 1, 4),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'A restaurant has leftover food daily. What is the most creative sustainable solution?', 'multiple_choice', '[{"text": "Throw it away", "value": "a"}, {"text": "Partner with food banks and create a discount app for last-hour deals", "value": "b"}, {"text": "Give it to staff only", "value": "c"}, {"text": "Reduce portions", "value": "d"}]', 1, 'This solution creatively addresses waste by combining social good (food banks) with business opportunity (discount app).', 'intermediate', 1, 5),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'What is the best way to encourage creative thinking in a team?', 'multiple_choice', '[{"text": "Punish failures", "value": "a"}, {"text": "Create a safe space for wild ideas without judgment", "value": "b"}, {"text": "Only accept proven solutions", "value": "c"}, {"text": "Work in isolation", "value": "d"}]', 1, 'Psychological safety and freedom from judgment are essential for fostering creative thinking and innovation.', 'beginner', 1, 6),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'You need to improve team collaboration but have no budget. What is most creative?', 'multiple_choice', '[{"text": "Do nothing", "value": "a"}, {"text": "Create themed lunch-and-learn sessions where team members share hobbies", "value": "b"}, {"text": "Send more emails", "value": "c"}, {"text": "Have longer meetings", "value": "d"}]', 1, 'This solution creatively builds relationships and knowledge sharing without any budget by leveraging existing resources (lunch time).', 'intermediate', 1, 7),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'Which technique helps generate the most creative ideas?', 'multiple_choice', '[{"text": "SCAMPER (Substitute, Combine, Adapt, Modify, Put to other uses, Eliminate, Reverse)", "value": "a"}, {"text": "Copying competitors", "value": "b"}, {"text": "Following strict rules", "value": "c"}, {"text": "Avoiding brainstorming", "value": "d"}]', 0, 'SCAMPER is a proven creative thinking technique that systematically explores different ways to innovate on existing ideas.', 'intermediate', 1, 8),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'A product launch failed. What is the most creative recovery strategy?', 'multiple_choice', '[{"text": "Give up on the product", "value": "a"}, {"text": "Turn the failure story into a transparent documentary series showing the pivot", "value": "b"}, {"text": "Blame the team", "value": "c"}, {"text": "Hide the failure", "value": "d"}]', 1, 'This approach creatively turns a negative into authentic content that builds trust and shows resilience, potentially creating more engagement than success would have.', 'advanced', 1, 9),

('85ec5362-03d7-4922-9300-1592e3c5abec', 'What mindset best supports creative problem-solving?', 'multiple_choice', '[{"text": "Fixed mindset focused on perfection", "value": "a"}, {"text": "Growth mindset embracing experiments and learning from failures", "value": "b"}, {"text": "Risk-averse mindset", "value": "c"}, {"text": "Competitive mindset only", "value": "d"}]', 1, 'A growth mindset allows for experimentation, learning, and iteration - all essential for creative problem-solving.', 'beginner', 1, 10);

-- Add questions for Critical Thinking
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer_index, explanation, difficulty, points, display_order) VALUES
('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'What is the first step in critical thinking?', 'multiple_choice', '[{"text": "Make a decision quickly", "value": "a"}, {"text": "Identify and question assumptions", "value": "b"}, {"text": "Accept information at face value", "value": "c"}, {"text": "Follow popular opinion", "value": "d"}]', 1, 'Critical thinking begins with identifying and questioning underlying assumptions rather than accepting information without analysis.', 'beginner', 1, 1),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'Which logical fallacy is this: "Everyone is buying this product, so it must be good"?', 'multiple_choice', '[{"text": "Strawman argument", "value": "a"}, {"text": "Bandwagon fallacy (appeal to popularity)", "value": "b"}, {"text": "False dichotomy", "value": "c"}, {"text": "Ad hominem", "value": "d"}]', 1, 'The bandwagon fallacy assumes something is true or good simply because many people believe or do it.', 'intermediate', 1, 2),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'A study claims coffee causes cancer. What should you evaluate first?', 'multiple_choice', '[{"text": "Stop drinking coffee immediately", "value": "a"}, {"text": "Check the study methodology, sample size, and funding sources", "value": "b"}, {"text": "Ignore it completely", "value": "c"}, {"text": "Share it on social media", "value": "d"}]', 1, 'Critical thinking requires evaluating the source, methodology, and potential biases before accepting claims as fact.', 'intermediate', 1, 3),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'Which statement demonstrates good critical thinking?', 'multiple_choice', '[{"text": "This must be true because an expert said it", "value": "a"}, {"text": "While this expert has credentials, I should verify the claim with multiple sources", "value": "b"}, {"text": "I believe it because I want it to be true", "value": "c"}, {"text": "Everyone knows this is true", "value": "d"}]', 1, 'Good critical thinking involves verification and not relying solely on authority, even when sources are credible.', 'intermediate', 1, 4),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'What is confirmation bias?', 'multiple_choice', '[{"text": "Accepting all information equally", "value": "a"}, {"text": "The tendency to seek and interpret information that confirms existing beliefs", "value": "b"}, {"text": "Being open to changing your mind", "value": "c"}, {"text": "Having no opinions", "value": "d"}]', 1, 'Confirmation bias is a cognitive bias where we favor information that confirms our preexisting beliefs while dismissing contradictory evidence.', 'intermediate', 1, 5),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'Which question best demonstrates critical analysis?', 'multiple_choice', '[{"text": "Who said this?", "value": "a"}, {"text": "What evidence supports this claim and what are alternative explanations?", "value": "b"}, {"text": "Do I like this idea?", "value": "c"}, {"text": "Is this popular?", "value": "d"}]', 1, 'This question focuses on evidence and alternative explanations, which are core to critical thinking rather than emotional or social factors.', 'intermediate', 1, 6),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'A politician says "You are either with us or against us." What fallacy is this?', 'multiple_choice', '[{"text": "Appeal to emotion", "value": "a"}, {"text": "False dichotomy (black-and-white thinking)", "value": "b"}, {"text": "Circular reasoning", "value": "c"}, {"text": "Slippery slope", "value": "d"}]', 1, 'False dichotomy presents only two options when more possibilities exist, oversimplifying complex situations.', 'intermediate', 1, 7),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'What is the best approach when encountering conflicting information?', 'multiple_choice', '[{"text": "Believe the first source you read", "value": "a"}, {"text": "Examine the quality of evidence for each position and look for common ground", "value": "b"}, {"text": "Believe whoever is more confident", "value": "c"}, {"text": "Ignore both sides", "value": "d"}]', 1, 'Critical thinking involves evaluating the strength of evidence for different positions rather than using shortcuts like chronology or confidence.', 'intermediate', 1, 8),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'Which is the strongest form of evidence in critical analysis?', 'multiple_choice', '[{"text": "Personal anecdotes", "value": "a"}, {"text": "Peer-reviewed scientific studies with replication", "value": "b"}, {"text": "Celebrity endorsements", "value": "c"}, {"text": "Social media posts", "value": "d"}]', 1, 'Peer-reviewed studies with replication provide the strongest evidence as they undergo rigorous scrutiny and independent verification.', 'intermediate', 1, 9),

('cf6157c9-218a-4b42-bf66-bf824d1e0abf', 'What does it mean to "steel man" an argument?', 'multiple_choice', '[{"text": "Make your opponent look weak", "value": "a"}, {"text": "Present the strongest version of the opposing argument before refuting it", "value": "b"}, {"text": "Ignore opposing viewpoints", "value": "c"}, {"text": "Attack the person making the argument", "value": "d"}]', 1, 'Steel manning means presenting the best version of an opposing argument, showing intellectual honesty and strong critical thinking.', 'advanced', 1, 10);

-- Add questions for Public Speaking
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer_index, explanation, difficulty, points, display_order) VALUES
('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'What is the most important element of effective public speaking?', 'multiple_choice', '[{"text": "Using big words", "value": "a"}, {"text": "Understanding and connecting with your audience", "value": "b"}, {"text": "Speaking very fast", "value": "c"}, {"text": "Memorizing every word", "value": "d"}]', 1, 'Effective public speaking starts with understanding your audience and tailoring your message to connect with them.', 'beginner', 1, 1),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'How should you handle nervousness before speaking?', 'multiple_choice', '[{"text": "Try to eliminate all nervousness", "value": "a"}, {"text": "Channel nervous energy into enthusiasm and use breathing techniques", "value": "b"}, {"text": "Avoid public speaking", "value": "c"}, {"text": "Speak very quietly", "value": "d"}]', 1, 'Some nervousness is natural and can be channeled positively. Breathing techniques help manage anxiety without trying to eliminate it completely.', 'beginner', 1, 2),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'What is the rule of three in public speaking?', 'multiple_choice', '[{"text": "Speak for only 3 minutes", "value": "a"}, {"text": "Present information in groups of three for better retention", "value": "b"}, {"text": "Have exactly 3 slides", "value": "c"}, {"text": "Speak to only 3 people", "value": "d"}]', 1, 'The rule of three suggests that information presented in threes is more memorable and effective in communication.', 'intermediate', 1, 3),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'What makes a strong opening for a speech?', 'multiple_choice', '[{"text": "Starting with boring statistics", "value": "a"}, {"text": "A compelling story, surprising fact, or thought-provoking question", "value": "b"}, {"text": "Apologizing for wasting their time", "value": "c"}, {"text": "Reading from notes immediately", "value": "d"}]', 1, 'Strong openings grab attention through stories, surprising facts, or questions that engage the audience immediately.', 'intermediate', 1, 4),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'How should you use eye contact during a presentation?', 'multiple_choice', '[{"text": "Stare at one person the whole time", "value": "a"}, {"text": "Make brief eye contact with individuals throughout the audience", "value": "b"}, {"text": "Look at the ceiling", "value": "c"}, {"text": "Close your eyes", "value": "d"}]', 1, 'Distributing eye contact across the audience creates connection and engagement with all attendees.', 'beginner', 1, 5),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'What is the purpose of pausing during a speech?', 'multiple_choice', '[{"text": "To show you forgot what to say", "value": "a"}, {"text": "To emphasize key points and give the audience time to process information", "value": "b"}, {"text": "To waste time", "value": "c"}, {"text": "To make the speech longer", "value": "d"}]', 1, 'Strategic pauses emphasize important points and allow the audience to absorb and reflect on what was said.', 'intermediate', 1, 6),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'How should you handle questions you cannot answer?', 'multiple_choice', '[{"text": "Make up an answer", "value": "a"}, {"text": "Acknowledge you don''t know and offer to follow up with accurate information", "value": "b"}, {"text": "Get angry at the questioner", "value": "c"}, {"text": "Change the subject quickly", "value": "d"}]', 1, 'Honesty and commitment to follow up maintains credibility better than making up answers or avoiding the question.', 'intermediate', 1, 7),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'What is the best way to conclude a speech?', 'multiple_choice', '[{"text": "Just stop talking suddenly", "value": "a"}, {"text": "Summarize key points and end with a memorable call to action or thought", "value": "b"}, {"text": "Introduce new topics", "value": "c"}, {"text": "Apologize for your performance", "value": "d"}]', 1, 'Strong conclusions reinforce the main message through summary and leave the audience with a clear takeaway or action.', 'intermediate', 1, 8),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'What role does body language play in public speaking?', 'multiple_choice', '[{"text": "It doesn''t matter", "value": "a"}, {"text": "It conveys confidence and can reinforce or contradict your message", "value": "b"}, {"text": "You should never move", "value": "c"}, {"text": "Only words matter", "value": "d"}]', 1, 'Body language is crucial as it can strengthen your message or create inconsistency if it contradicts your words.', 'beginner', 1, 9),

('37c21e6a-28a7-437a-9d1c-ab5f28ed392b', 'How should you prepare for a presentation?', 'multiple_choice', '[{"text": "Wing it without preparation", "value": "a"}, {"text": "Research audience, practice multiple times, prepare for questions", "value": "b"}, {"text": "Memorize word-for-word", "value": "c"}, {"text": "Write everything on slides", "value": "d"}]', 1, 'Thorough preparation includes understanding your audience, practicing delivery, and anticipating questions while maintaining flexibility.', 'intermediate', 1, 10);

-- Add questions for UI/UX Design
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer_index, explanation, difficulty, points, display_order) VALUES
('96bac778-5a42-438c-84e7-bb863b2c052b', 'What does UX stand for?', 'multiple_choice', '[{"text": "User Experience", "value": "a"}, {"text": "Universal Export", "value": "b"}, {"text": "Unique eXecution", "value": "c"}, {"text": "User eXport", "value": "d"}]', 0, 'UX stands for User Experience, which encompasses all aspects of the end-user''s interaction with a product or service.', 'beginner', 1, 1),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is the primary goal of UI/UX design?', 'multiple_choice', '[{"text": "Make things look pretty", "value": "a"}, {"text": "Create intuitive, efficient, and enjoyable user experiences", "value": "b"}, {"text": "Use as many colors as possible", "value": "c"}, {"text": "Copy competitor designs", "value": "d"}]', 1, 'The primary goal is to create experiences that are intuitive, efficient, and enjoyable, solving user problems effectively.', 'beginner', 1, 2),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is a wireframe?', 'multiple_choice', '[{"text": "The final design", "value": "a"}, {"text": "A low-fidelity blueprint showing structure and layout without detailed design", "value": "b"}, {"text": "A type of programming code", "value": "c"}, {"text": "A color palette", "value": "d"}]', 1, 'Wireframes are low-fidelity visual guides that represent the skeletal framework of a website or app, focusing on layout and functionality.', 'intermediate', 1, 3),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What does "F-pattern" refer to in web design?', 'multiple_choice', '[{"text": "A font style", "value": "a"}, {"text": "The pattern users'' eyes follow when scanning content (horizontal then vertical)", "value": "b"}, {"text": "A type of layout grid", "value": "c"}, {"text": "A failure pattern", "value": "d"}]', 1, 'The F-pattern describes how users typically scan web content - horizontally across the top, then down the left side, forming an F shape.', 'intermediate', 1, 4),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is the principle of "affordance" in design?', 'multiple_choice', '[{"text": "Making things expensive", "value": "a"}, {"text": "Design cues that suggest how an object should be used", "value": "b"}, {"text": "Using only free resources", "value": "c"}, {"text": "Designing for affordability", "value": "d"}]', 1, 'Affordance refers to design characteristics that suggest how an element should be used (e.g., a button that looks clickable).', 'intermediate', 1, 5),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is the recommended minimum touch target size for mobile?', 'multiple_choice', '[{"text": "10x10 pixels", "value": "a"}, {"text": "44x44 pixels (or about 9mm)", "value": "b"}, {"text": "100x100 pixels", "value": "c"}, {"text": "Size doesn''t matter", "value": "d"}]', 1, 'The recommended minimum touch target size is 44x44 pixels (about 9mm) to ensure easy interaction with fingers of various sizes.', 'intermediate', 1, 6),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is A/B testing in UX?', 'multiple_choice', '[{"text": "Testing two different apps", "value": "a"}, {"text": "Comparing two versions of a design to see which performs better", "value": "b"}, {"text": "Grading system", "value": "c"}, {"text": "Testing alphabets", "value": "d"}]', 1, 'A/B testing involves showing two variants of a design to different user groups to determine which performs better based on measurable criteria.', 'intermediate', 1, 7),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is the purpose of a design system?', 'multiple_choice', '[{"text": "To limit creativity", "value": "a"}, {"text": "To maintain consistency with reusable components and guidelines", "value": "b"}, {"text": "To make designs boring", "value": "c"}, {"text": "To copy other companies", "value": "d"}]', 1, 'Design systems provide reusable components and guidelines to maintain consistency across products while improving efficiency.', 'intermediate', 1, 8),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is accessibility (a11y) in design?', 'multiple_choice', '[{"text": "Making designs expensive", "value": "a"}, {"text": "Ensuring products are usable by people with diverse abilities and disabilities", "value": "b"}, {"text": "Designing for only young users", "value": "c"}, {"text": "Using only one color", "value": "d"}]', 1, 'Accessibility ensures that products can be used by everyone, including people with visual, auditory, motor, or cognitive disabilities.', 'intermediate', 1, 9),

('96bac778-5a42-438c-84e7-bb863b2c052b', 'What is the difference between UI and UX?', 'multiple_choice', '[{"text": "They are the same thing", "value": "a"}, {"text": "UI focuses on visual design and interactions, UX encompasses the entire user experience", "value": "b"}, {"text": "UI is for mobile only", "value": "c"}, {"text": "UX is not important", "value": "d"}]', 1, 'UI (User Interface) deals with visual elements and interactions, while UX (User Experience) covers the complete experience including usability and satisfaction.', 'beginner', 1, 10);

-- Add questions for Written Communication
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer_index, explanation, difficulty, points, display_order) VALUES
('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'What is the most important rule in professional written communication?', 'multiple_choice', '[{"text": "Use complex vocabulary", "value": "a"}, {"text": "Be clear, concise, and consider your audience", "value": "b"}, {"text": "Write as much as possible", "value": "c"}, {"text": "Use only formal language", "value": "d"}]', 1, 'Effective written communication prioritizes clarity and conciseness while considering the audience''s needs and context.', 'beginner', 1, 1),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'Which sentence demonstrates active voice?', 'multiple_choice', '[{"text": "The report was completed by the team", "value": "a"}, {"text": "The team completed the report", "value": "b"}, {"text": "The report has been finished", "value": "c"}, {"text": "It was decided that the report be completed", "value": "d"}]', 1, 'Active voice places the subject (team) before the action (completed), making writing more direct and engaging.', 'intermediate', 1, 2),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'What is the purpose of a topic sentence in a paragraph?', 'multiple_choice', '[{"text": "To end the paragraph", "value": "a"}, {"text": "To introduce the main idea of the paragraph", "value": "b"}, {"text": "To add random information", "value": "c"}, {"text": "To confuse the reader", "value": "d"}]', 1, 'The topic sentence introduces the main idea of a paragraph, guiding readers on what to expect in the following sentences.', 'beginner', 1, 3),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'Which is the most professional email greeting for a business context?', 'multiple_choice', '[{"text": "Hey dude!", "value": "a"}, {"text": "Dear Mr./Ms. [Last Name],", "value": "b"}, {"text": "Yo!", "value": "c"}, {"text": "Wassup?", "value": "d"}]', 1, 'Formal business emails should use professional greetings with appropriate titles and last names.', 'beginner', 1, 4),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'What should you do before sending an important email?', 'multiple_choice', '[{"text": "Send it immediately", "value": "a"}, {"text": "Proofread for errors, check tone, and verify recipients", "value": "b"}, {"text": "Forward it to everyone", "value": "c"}, {"text": "Delete it", "value": "d"}]', 1, 'Important emails should be proofread for errors, checked for appropriate tone, and verified for correct recipients before sending.', 'beginner', 1, 5),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'What makes a good subject line in professional emails?', 'multiple_choice', '[{"text": "Long and detailed", "value": "a"}, {"text": "Clear, specific, and action-oriented", "value": "b"}, {"text": "All caps with many emojis", "value": "c"}, {"text": "Vague and mysterious", "value": "d"}]', 1, 'Good subject lines are clear, specific, and often action-oriented, helping recipients understand the email''s purpose immediately.', 'intermediate', 1, 6),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'Which transition word shows contrast?', 'multiple_choice', '[{"text": "Additionally", "value": "a"}, {"text": "However", "value": "b"}, {"text": "Furthermore", "value": "c"}, {"text": "Similarly", "value": "d"}]', 1, '"However" is a transition word that introduces a contrasting or opposing idea to what was previously stated.', 'intermediate', 1, 7),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'What is the recommended length for a professional business email?', 'multiple_choice', '[{"text": "As long as possible", "value": "a"}, {"text": "Concise - ideally 3-5 short paragraphs", "value": "b"}, {"text": "One word", "value": "c"}, {"text": "Exactly 10 pages", "value": "d"}]', 1, 'Professional emails should be concise, typically 3-5 short paragraphs, respecting the reader''s time while conveying necessary information.', 'intermediate', 1, 8),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'How should you structure a business proposal?', 'multiple_choice', '[{"text": "Random order of thoughts", "value": "a"}, {"text": "Executive summary, problem, solution, implementation, budget", "value": "b"}, {"text": "Only price information", "value": "c"}, {"text": "No structure needed", "value": "d"}]', 1, 'Business proposals should follow a logical structure: executive summary, problem identification, proposed solution, implementation plan, and budget.', 'intermediate', 1, 9),

('f1ea79f1-1d2f-4ad8-bf8f-639a32079428', 'What is the tone of this sentence: "You failed to submit the report on time."?', 'multiple_choice', '[{"text": "Positive and encouraging", "value": "a"}, {"text": "Negative and accusatory", "value": "b"}, {"text": "Neutral and professional", "value": "c"}, {"text": "Humorous", "value": "d"}]', 1, 'This sentence has a negative, accusatory tone. A more professional alternative would be: "I noticed the report wasn''t submitted by the deadline."', 'intermediate', 1, 10);